using UnityEngine;

namespace CatMerge.Data
{
    /// <summary>Static data of one cat level. Generated by Tools/CatMerge/Generate Cat Configs.</summary>
    [CreateAssetMenu(menuName = "CatMerge/Cat Config", fileName = "Cat_00")]
    public sealed class CatConfig : ScriptableObject
    {
        [Min(1)] public int level = 1;
        [Tooltip("Loc key of the display name, e.g. cat_01_name.")]
        public string nameKey;
        [Tooltip("Loc key of the short description, e.g. cat_01_desc.")]
        public string descKey;
        public Sprite sprite;
        [Tooltip("Tint of the placeholder body (multiplied with the sprite).")]
        public Color color = Color.white;
        [Tooltip("Coins per second produced by one cat of this level.")]
        public double incomePerSec = 1;
        [Tooltip("Played on spawn/merge/tap. Unique per level for the relax vibe.")]
        public AudioClip meowClip;

        private void OnValidate()
        {
            incomePerSec = System.Math.Max(0, incomePerSec);
        }
    }
}
